+    # notifications, and get an error response with "id": null.
+    if options.version == 2 and options.notification and not invalid:
         return None
     response = {}
     if not options.notification:
         response.update(id=idx)
+    elif options.version == 2:
+        response.update(id=None)
     if options.version == 2:
         response.update(jsonrpc="2.0")
     else:
